async function executeCommand(input: string, context?: CommandContext): Promise<{ output: CommandOutput[]; isClear: boolean }> {
  const trimmed = input.trim().toLowerCase()
  const [commandName, ...args] = trimmed.split(/\s+/)

  if (!commandName) {
    return { output: [], isClear: false }
  }

  if (commandName === "clear") {
    return { output: [], isClear: true }
  }

  const command = commandRegistry.get(commandName)

  if (!command) {
    return {
      output: [
        { text: "", className: "" },
        { text: `  Command not found: ${commandName}`, className: "text-red-400/80" },
        { text: "  Type 'help' to see available commands.", className: "text-zinc-600 text-xs" },
        { text: "", className: "" },
      ],
      isClear: false,
    }
  }

  const output = await command.execute(args, context)
  return { output, isClear: false }
}

